installer-gui-script.script:
function checkPowerPoint() {
  if (!system.applications.fromIdentifier('com.microsoft.Powerpoint')) {
    my.result.type = 'Fatal';
    my.result.title = 'PowerPoint isn’t installed';
    my.result.message = 'Font Manager is an add-in for Microsoft PowerPoint for Mac. Install PowerPoint, open it once, then run this installer again.';
    return false;
  }
  // The wef folder lives in PowerPoint's sandbox container, which PowerPoint
  // creates the first time it runs. Making it by hand before then is asking
  // for a container macOS doesn't recognise.
  var home = system.env.HOME;
  if (home && !system.files.fileExistsAtPath(home + '/Library/Containers/com.microsoft.Powerpoint')) {
    my.result.type = 'Fatal';
    my.result.title = 'Open PowerPoint once first';
    my.result.message = 'PowerPoint hasn’t been opened on this account yet, so it has nowhere to keep add-ins. Open PowerPoint, quit it, then run this installer again.';
    return false;
  }
  return true;
}
